package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Actual UI events and durable ownership; temporary fixtures only, no external transactions. */
final class RedesignChecks {
 static int checks;static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static void main(Instrumentation i,Runnable run){Throwable[] error={null};i.runOnMainSync(()->{try{run.run();}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new AssertionError(error[0]);}
 static String texts(View view){StringBuilder out=new StringBuilder();if(view instanceof TextView)out.append(((TextView)view).getText()).append('\n');if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++)out.append(texts(((ViewGroup)view).getChildAt(n)));return out.toString();}
 static View find(View view,String description){if(description.equals(view.getContentDescription()))return view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){View hit=find(((ViewGroup)view).getChildAt(n),description);if(hit!=null)return hit;}return null;}
 static void migration(Instrumentation i)throws Exception{java.io.File dir=new java.io.File(i.getTargetContext().getCacheDir(),"ui050-migration-"+System.nanoTime());dir.mkdirs();Context isolated=new ContextWrapper(i.getTargetContext()){@Override public java.io.File getDatabasePath(String name){return new java.io.File(dir,name);}@Override public android.database.sqlite.SQLiteDatabase openOrCreateDatabase(String name,int mode,android.database.sqlite.SQLiteDatabase.CursorFactory factory){return android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name),factory);}@Override public android.database.sqlite.SQLiteDatabase openOrCreateDatabase(String name,int mode,android.database.sqlite.SQLiteDatabase.CursorFactory factory,android.database.DatabaseErrorHandler handler){return android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name).getPath(),factory,handler);}};
 String goal;try(GoalStore legacy=new GoalStore(isolated)){goal=legacy.create("home","REGRESSION_MIGRATE","집",0).optString("id");JSONArray history=new JSONArray();for(int n=0;n<86;n++)history.put(GoalStore.put(GoalStore.put(new JSONObject(),"role","user"),"text","원본 기록 "+n));JSONObject patch=new JSONObject();GoalStore.put(patch,"chatMessages",history);GoalStore.put(patch,"chatDraft","원본 초안");legacy.patchGoal(goal,patch);for(String table:new String[]{"conversations","runs","artifacts"})legacy.getWritableDatabase().execSQL("DROP TABLE "+table);legacy.getWritableDatabase().setVersion(2);}
 try(GoalStore migrated=new GoalStore(isolated)){check(migrated.getReadableDatabase().getVersion()==3,"goal DB v2 to v3 migration");check(migrated.workspace("conversations",goal).size()==1,"migration makes one previous conversation");JSONObject row=migrated.defaultConversation(goal);check(row.optJSONArray("messages").length()==86,"migration preserves all 86 original messages");check(row.optString("draft").equals("원본 초안"),"migration preserves draft");check(migrated.goal(goal).optJSONArray("chatMessages").length()==86,"legacy goal JSON preserved");}
 try(TaskStore tasks=new TaskStore(isolated)){tasks.getWritableDatabase().execSQL("INSERT INTO tasks(title,kind,state,updated,due) VALUES ('원본 일정','목표','대기',1,'2026-11-02')");try(android.database.Cursor row=tasks.getReadableDatabase().rawQuery("SELECT due,start_at,end_at,is_all_day FROM tasks",null)){check(row.moveToFirst()&&row.getString(0).equals("2026-11-02")&&row.isNull(1)&&row.isNull(2)&&row.getInt(3)==1,"legacy date stays all-day, not midnight");}}
 for(java.io.File f:dir.listFiles())f.delete();dir.delete();}
 static void run(Instrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;List<String> ids=new ArrayList<>();android.content.SharedPreferences prefs=i.getTargetContext().getSharedPreferences("nubi_navigation_v3",0);Map<String,?> original=new HashMap<>(prefs.getAll());try(GoalStore s=new GoalStore(i.getTargetContext())){
  JSONObject g=s.create("fitness","REGRESSION_UI050_A","운동",0),h=s.create("home","REGRESSION_UI050_B","집",0);String ga=g.optString("id"),gb=h.optString("id");ids.add(ga);ids.add(gb);JSONObject first=s.createConversation(ga,"첫 대화"),second=s.createConversation(ga,"둘째 대화");JSONArray messages=new JSONArray();for(int n=0;n<85;n++)messages.put(GoalStore.put(GoalStore.put(new JSONObject(),"role","user"),"text","기록 "+n));s.saveConversation(first.optString("id"),messages,"초안 A");s.saveConversation(second.optString("id"),new JSONArray(),"초안 B");check(s.workspaceRow("conversations",first.optString("id")).optJSONArray("messages").length()==85,"no truncation after 40");check(s.workspace("conversations",ga).size()==2,"two conversations same goal");check(s.workspace("conversations",gb).isEmpty(),"no implicit conversation in other goal");
  android.content.ContentValues calendar=TaskEditor.values("시험", "2026-11-02",false,"2026-11-02T10:00","2026-11-02T11:00","Asia/Seoul");check(calendar.getAsInteger("is_all_day")==0,"timed task distinct from all-day");check(calendar.getAsString("timezone").equals("Asia/Seoul"),"timezone stored");boolean invalid=false;try{TaskEditor.values("bad","",false,"2026-11-02T11:00","2026-11-02T10:00","Asia/Seoul");}catch(Exception e){invalid=true;}check(invalid,"end before start rejected");invalid=false;try{TaskEditor.values("DST","",false,"2026-11-01T01:30","2026-11-01T03:30","America/New_York");}catch(Exception e){invalid=true;}check(invalid,"ambiguous DST local time rejected");
  migration(i);
  a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",ga).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity host=a;
  main(i,()->{host.relay.stop();host.chat.switchConversation(ga,first.optString("id"));check(host.chat.input.getText().toString().equals("초안 A"),"first draft restored");host.chat.switchConversation(ga,second.optString("id"));check(host.chat.input.getText().toString().equals("초안 B"),"second draft isolated");host.chat.input.setText("보존 초안");host.chat.switchGoal(gb);host.chat.switchConversation(ga,second.optString("id"));check(host.chat.input.getText().toString().equals("보존 초안"),"draft preserved during goal switch");});
  main(i,()->{NubiCompanionUi u=host.chat.companion;View tab=find(u.dock,"나의 누비");check(tab!=null,"five navigation destinations include My");tab.performClick();check(u.page.equals("내 정보"),"My click opens global page");check(u.identity.getVisibility()==View.GONE,"global header excludes selected character");check(u.globalTitle.getText().toString().equals("나의 누비"),"global header title");String text=texts(u.sideBody);for(GoalRules.Preset p:GoalRules.PRESETS)check(text.contains(p.name+" · "),"all six agents visible: "+p.id);for(String page:new String[]{"친구","둘러보기","보관함"}){View target=find(u.dock,page);check(target!=null,"dock destination "+page);target.performClick();check(u.globalTitle.getText().toString().equals(page),"header "+page);}u.select("대화");check(u.identity.getVisibility()==View.VISIBLE,"chat character header restored");check(u.composer.getVisibility()==View.VISIBLE,"chat input restored");});
  main(i,()->{JSONObject run=new JSONObject();String rid=UUID.randomUUID().toString();GoalStore.put(run,"id",rid);GoalStore.put(run,"goalId",ga);GoalStore.put(run,"conversationId",second.optString("id"));GoalStore.put(run,"character","fitness");GoalStore.put(run,"requestId",UUID.randomUUID().toString());GoalStore.put(run,"jobId",UUID.randomUUID().toString());GoalStore.put(run,"state","RUNNING");GoalStore.put(run,"steps",new JSONArray());host.runs.run=run;host.runs.save();host.chat.switchGoal(gb);check(host.runs.active()!=null,"goal switch keeps active run");check(host.gid.equals(ga),"browser execution goal unchanged");check(host.chat.goalId.equals(gb),"presentation goal changes independently");check(host.chat.companion.runBanner.getVisibility()==View.VISIBLE,"persistent global run banner");JSONObject result=new JSONObject();GoalStore.put(result,"answer","REGRESSION_TEST_RESULT");host.runs.complete("completed",result);check(host.runs.active()==null,"terminal result ends active lease");check(host.chat.goalId.equals(gb),"completion keeps current selection");JSONArray originalHistory=s.workspaceRow("conversations",second.optString("id")).optJSONArray("messages");check(originalHistory.toString().contains("REGRESSION_TEST_RESULT"),"result stored in original conversation");check(!host.chat.history.toString().contains("REGRESSION_TEST_RESULT"),"result not injected into other goal");host.chat.switchConversation(ga,first.optString("id"));host.chat.save();check(s.workspaceRow("conversations",first.optString("id")).optJSONArray("messages").length()==85,"render/save preserves all 85 messages");});
  main(i,()->{int before=s.goals().size();host.chat.switchConversation("","");host.chat.companion.select("내 정보");check(s.goals().size()==before,"global navigation never creates a goal");check(texts(host.chat.companion.sideBody).contains("아직 목표가 없어요"),"empty agent state visible");check(host.chat.goalId.isEmpty(),"empty selected goal supported");});
  out.putString("stream","PASS "+checks+" redesign ownership, navigation and persistence checks\n");
 }catch(Throwable t){out.putString("stream","FAIL "+t+"\n");}finally{if(a!=null){GoalAgentActivity host=a;main(i,host::finish);i.waitForIdleSync();}try(GoalStore s=new GoalStore(i.getTargetContext())){for(String id:ids)s.deleteGoal(id);}android.content.SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> e:original.entrySet())if(e.getValue() instanceof String)edit.putString(e.getKey(),(String)e.getValue());edit.commit();i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}}
}
